//#region src/components/SkeletonPlaceholder/SkeletonPlaceholder.tsx
const SkeletonPlaceholder = ({ className, ...other }) => {
	const prefix = usePrefix();
	const skeletonPlaceholderClasses = cx({ [`${prefix}--skeleton__placeholder`]: true }, className);
	return /* @__PURE__ */ jsx("div", {
		className: skeletonPlaceholderClasses,
		...other
	});
};
